"""Further validators over depot run outputs. Each ``VN`` subclasses ``Check`` from ``checks_base``.

Callers use ``VN().run(items)``. ``Check.run`` handles empty input and "nothing measured";
each ``check`` returns ``(passed, measured)`` where ``measured`` is always a non-empty dict.
"""
from __future__ import annotations

from collections import Counter

from checks_base import Check

# Inclusive bounds for supplier reliability. The spec does not state them; see notes.
RELIABILITY_MIN = 0
RELIABILITY_MAX = 100


def is_over_capacity(entry) -> bool:
    return entry["max_units"] > entry["capacity"]


def unnotified_expiries(entry) -> list:
    """Expired [sku, wh, qty] triples not matched by a notified triple (multiset difference)."""
    expired = Counter(tuple(item) for item in entry["expired"])
    notified = Counter(tuple(item) for item in entry["notified"])
    return [list(item) for item in (expired - notified).elements()]


def is_reliability_in_range(entry) -> bool:
    return RELIABILITY_MIN <= entry["reliability"] <= RELIABILITY_MAX


class V7(Check):
    """entries: every warehouse's capacity was respected across runs (max_units <= capacity)."""

    name = "entries"

    def check(self, items):
        over = []
        for entry in items:
            if is_over_capacity(entry):
                over.append(
                    {
                        "wh": entry["wh"],
                        "capacity": entry["capacity"],
                        "max_units": entry["max_units"],
                    }
                )
        measured = {"entries_checked": len(items), "over_capacity": over}
        return (not over), measured


class V8(Check):
    """entries: all expiries were notified (every expired [sku, wh, qty] has a matching notice)."""

    name = "entries"

    def check(self, items):
        unnotified = []
        for entry in items:
            unnotified.extend(unnotified_expiries(entry))
        measured = {"entries_checked": len(items), "unnotified": unnotified}
        return (not unnotified), measured


class V9(Check):
    """entries: every supplier's reliability stayed within [RELIABILITY_MIN, RELIABILITY_MAX]."""

    name = "entries"

    def check(self, items):
        out_of_range = []
        for entry in items:
            if not is_reliability_in_range(entry):
                out_of_range.append(
                    {"supplier": entry["supplier"], "reliability": entry["reliability"]}
                )
        measured = {"entries_checked": len(items), "out_of_range": out_of_range}
        return (not out_of_range), measured
