"""Tests for validators_later. Run with: python -m unittest test_validators_later"""
import unittest

from validators_later import V7, V8, V9


class TestV7(unittest.TestCase):
    def test_passes_when_within_capacity(self):
        items = [{"wh": "A", "capacity": 10, "max_units": 10}]
        passed, measured = V7().run(items)
        self.assertTrue(passed)
        self.assertEqual(measured["over_capacity"], [])

    def test_fails_when_over_capacity(self):
        items = [
            {"wh": "A", "capacity": 10, "max_units": 10},
            {"wh": "B", "capacity": 5, "max_units": 7},
        ]
        passed, measured = V7().run(items)
        self.assertFalse(passed)
        self.assertEqual(
            measured["over_capacity"],
            [{"wh": "B", "capacity": 5, "max_units": 7}],
        )

    def test_empty_input_fails(self):
        self.assertFalse(V7().run([]).passed)


class TestV8(unittest.TestCase):
    def test_passes_when_all_expiries_notified(self):
        items = [
            {
                "expired": [["S1", "W1", 3]],
                "notified": [["S1", "W1", 3], ["S2", "W1", 1]],
            }
        ]
        passed, measured = V8().run(items)
        self.assertTrue(passed)
        self.assertEqual(measured["unnotified"], [])

    def test_fails_when_expiry_not_notified(self):
        items = [{"expired": [["S1", "W1", 3]], "notified": []}]
        passed, measured = V8().run(items)
        self.assertFalse(passed)
        self.assertEqual(measured["unnotified"], [["S1", "W1", 3]])

    def test_duplicate_expiries_need_duplicate_notices(self):
        items = [
            {
                "expired": [["S1", "W1", 3], ["S1", "W1", 3]],
                "notified": [["S1", "W1", 3]],
            }
        ]
        passed, measured = V8().run(items)
        self.assertFalse(passed)
        self.assertEqual(measured["unnotified"], [["S1", "W1", 3]])

    def test_empty_lists_in_entry_still_measured(self):
        items = [{"expired": [], "notified": []}]
        passed, measured = V8().run(items)
        self.assertTrue(passed)
        self.assertEqual(measured["entries_checked"], 1)

    def test_empty_input_fails(self):
        self.assertFalse(V8().run([]).passed)


class TestV9(unittest.TestCase):
    def test_passes_at_bounds(self):
        items = [
            {"supplier": "X", "reliability": 0},
            {"supplier": "Y", "reliability": 100},
        ]
        passed, measured = V9().run(items)
        self.assertTrue(passed)
        self.assertEqual(measured["out_of_range"], [])

    def test_fails_when_out_of_range(self):
        items = [
            {"supplier": "X", "reliability": 50},
            {"supplier": "Y", "reliability": 101},
            {"supplier": "Z", "reliability": -1},
        ]
        passed, measured = V9().run(items)
        self.assertFalse(passed)
        self.assertEqual(
            measured["out_of_range"],
            [
                {"supplier": "Y", "reliability": 101},
                {"supplier": "Z", "reliability": -1},
            ],
        )

    def test_empty_input_fails(self):
        self.assertFalse(V9().run([]).passed)


if __name__ == "__main__":
    unittest.main()
